import pandas as pd
from io import StringIO
def task_func(url, table_id):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("URL must be a non-empty string")
    if not isinstance(table_id, str) or not table_id.strip():
        raise ValueError("table_id must be a non-empty string")

    response = requests.get(url)
    try:
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        raise

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)
    if table is None:
        raise ValueError("Table with the specified ID not found.")

    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()

    header_cells = rows[0].find_all(['th', 'td'])
    headers = [cell.get_text(strip=True) for cell in header_cells]
    has_header = any(headers)

    data = []
    start_index = 1 if has_header else 0
    for row in rows[start_index:]:
        cells = row.find_all('td')
        if not cells:
            continue
        row_data = [cell.get_text(strip=True) for cell in cells]
        data.append(row_data)

    if not data and has_header:
        return pd.DataFrame(columns=headers)
    if not data:
        return pd.DataFrame()

    max_len = max(len(r) for r in data)
    for r in data:
        if len(r) < max_len:
            r.extend([''] * (max_len - len(r)))

    if has_header and len(headers) == max_len:
        df = pd.DataFrame(data, columns=headers)
    else:
        df = pd.DataFrame(data)

    return df

