import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    content = ""
    is_url = webpage_url.startswith("http://") or webpage_url.startswith("https://")
    if is_url:
        try:
            response = requests.get(webpage_url)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Error fetching URL content: {e}")
    else:
        try:
            with open(webpage_url, "r", encoding="utf-8") as f:
                content = f.read()
        except OSError as e:
            raise requests.RequestException(f"Error reading local HTML file: {e}")
    if not content:
        return 0
    try:
        tree = html.fromstring(content)
        table = tree.xpath("//table")[0] if tree.xpath("//table") else None
    except Exception:
        table = None
    if table is None:
        return 0
    header_cells = table.xpath(".//tr[th]/th")
    headers = [cell.text_content().strip() for cell in header_cells] if header_cells else []
    rows = []
    for row in table.xpath(".//tr"):
        cells = row.xpath("./td")
        if not cells:
            data_cells = row.xpath("./th")
            if not data_cells or row.xpath("./th") == header_cells:
                continue
            cells = data_cells
        row_values = [c.text_content().strip() for c in cells]
        if any(v != "" for v in row_values):
            rows.append(row_values)
    if not rows:
        return 0
    max_len = max(len(r) for r in rows)
    normalized_rows = [r + [""] * (max_len - len(r)) for r in rows]
    if headers:
        if len(headers) < max_len:
            headers = headers + [f"col_{i}" for i in range(len(headers) + 1, max_len + 1)]
        elif len(headers) > max_len:
            headers = headers[:max_len]
        df = pd.DataFrame(normalized_rows, columns=headers)
    else:
        df = pd.DataFrame(normalized_rows)
    try:
        conn = sqlite3.connect(database_name)
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Error connecting to database: {e}")
    try:
        df.to_sql("my_table", conn, if_exists="replace", index=False)
    except sqlite3.DatabaseError as e:
        conn.close()
        raise sqlite3.DatabaseError(f"Error writing to database: {e}")
    finally:
        conn.close()
    return len(df)

