import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if webpage_url.lower().startswith(("http://", "https://")):
        try:
            response = requests.get(webpage_url)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Error accessing URL: {e}")
    else:
        with open(webpage_url, "r", encoding="utf-8") as f:
            content = f.read()
    tree = html.fromstring(content)
    tables = tree.xpath("//table")
    if not tables:
        return 0
    table = tables[0]
    rows = table.xpath(".//tr")
    data = []
    for row in rows:
        cells = row.xpath(".//th|.//td")
        if not cells:
            continue
        data.append([cell.text_content().strip() for cell in cells])
    if not data:
        return 0
    header_len = len(data[0])
    headers = data[0]
    body = data[1:]
    if any(len(r) != header_len for r in body):
        body_fixed = []
        for r in body:
            if len(r) < header_len:
                r = r + [None] * (header_len - len(r))
            elif len(r) > header_len:
                r = r[:header_len]
            body_fixed.append(r)
        body = body_fixed
    df = pd.DataFrame(body, columns=headers)
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.close()
