import json
import requests
def task_func(API_URL, endpoint, PREFIX):
    if not isinstance(API_URL, str) or not API_URL:
        raise RuntimeError("API_URL must be a non-empty string")
    if not isinstance(endpoint, str) or not endpoint:
        raise RuntimeError("endpoint must be a non-empty string")
    if not isinstance(PREFIX, str) or not PREFIX:
        raise RuntimeError("PREFIX must be a non-empty string")
    base = API_URL.rstrip('/')
    ep = endpoint.lstrip('/')
    url = base + '/' + ep
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise RuntimeError(f"Error fetching data from API: {e}")
    try:
        data = response.json()
    except json.JSONDecodeError as e:
        raise RuntimeError(f"Error decoding JSON from API response: {e}")
    endpoint_name = ep.strip('/')
    if not endpoint_name:
        endpoint_name = "root"
    safe_endpoint = endpoint_name.replace('/', '_')
    filename = f"{PREFIX}{safe_endpoint}.json"
    try:
        with open(filename, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except OSError as e:
        raise RuntimeError(f"Error writing JSON to file: {e}")
    return filename

