def task_func(API_URL, endpoint, PREFIX):
    if not isinstance(API_URL, str) or not API_URL:
        raise RuntimeError("API_URL must be a non-empty string")
    if not isinstance(endpoint, str) or not endpoint:
        raise RuntimeError("endpoint must be a non-empty string")
    if not isinstance(PREFIX, str) or not PREFIX:
        raise RuntimeError("PREFIX must be a non-empty string")
    base = API_URL.rstrip('/')
    ep = endpoint.strip('/')
    url = base + '/' + ep if ep else base
    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise RuntimeError(f"Error fetching data from API: {e}")
    filename_endpoint_part = ep.replace('/', '_') if ep else 'root'
    filename = f"{PREFIX}{filename_endpoint_part}.json"
    try:
        with open(filename, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception as e:
        raise RuntimeError(f"Error writing data to file: {e}")
    return filename

import collections
import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not isinstance(user, str) or not user.strip():
        raise ValueError("User must be a non-empty string.")
    url = API_URL.rstrip("/") + "/" + user.strip() + "/repos"
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.ConnectionError as e:
        raise ConnectionError(f"Failed to connect to GitHub API: {e}")
    except requests.HTTPError as e:
        raise requests.HTTPError(f"GitHub API returned an error: {e}")
    try:
        data = response.json()
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse GitHub API response: {e}")
    if not isinstance(data, list):
        return []
    RepoInfo = collections.namedtuple("RepoInfo", ["name", "created_at"])
    repos = []
    for item in data:
        name = item.get("name")
        created_at = item.get("created_at")
        if name is None or created_at is None:
            continue
        repos.append(RepoInfo(name=name, created_at=created_at))
    repos_sorted = sorted(repos, key=lambda r: r.created_at)
    return [r.name for r in repos_sorted]

