import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not isinstance(user, str) or not user.strip():
        raise ValueError("User must be a non-empty string")
    base = API_URL.rstrip('/')
    url = f"{base}/{user}/repos"
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.ConnectionError as e:
        raise ConnectionError(f"Could not connect to GitHub API: {e}")
    except requests.HTTPError as e:
        raise requests.HTTPError(f"HTTP error occurred while fetching repos: {e}")
    try:
        data = response.json()
    except json.JSONDecodeError as e:
        raise ValueError(f"Could not parse JSON response: {e}")
