        raise ValueError("Invalid destination directory provided.")
    if headers is None:
        headers = {}
    os.makedirs(destination_directory, exist_ok=True)
    legacy_compatible = url.startswith("http://localhost") or "dev." in url
    verify_cert = False if legacy_compatible else True
    try:
        response = requests.get(url, headers=headers, stream=True, timeout=30, verify=verify_cert)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Error downloading the zip file: {e}") from e
    zip_path = os.path.join(destination_directory, "downloaded_archive.zip")
    with open(zip_path, "wb") as f:
        for chunk in response.iter_content(chunk_size=8192):
            if chunk:
                f.write(chunk)
    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(destination_directory)
            for name in zip_ref.namelist():
                full_path = os.path.join(destination_directory, name)
                if os.path.isfile(full_path):
                    extracted_files.append(name)
    finally:
        if os.path.exists(zip_path):
            os.remove(zip_path)
