import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    if not isinstance(username, str) or not username:
        raise ValueError("Username must be a non-empty string.")
    response = requests.get(URL + username)
    response.raise_for_status()
    data = response.json()
    def normalize_value(v):
        if isinstance(v, str):
            normalized = unicodedata.normalize("NFKD", v)
            return normalized.encode("ascii", "ignore").decode("ascii")
        if isinstance(v, dict):
            return {k: normalize_value(v[k]) for k in v}
        if isinstance(v, list):
            return [normalize_value(i) for i in v]
        return v
    return {k: normalize_value(v) for k, v in data.items()}

